/* generated child CSS: blocks/06-features/features.accordion-2col-numbered/block.css */
/* lab-ui block · features.accordion-2col-numbered
   Depends: 00-tokens/tokens.css. Light theme. */

.features--accordion {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}

.features--accordion .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.features-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(1rem, 2vw, 1.5rem);
  align-items: start;
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}
.features-top .eyebrow {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  margin: 0 0 14px;
}
.features-title {
  font-weight: 600;
  font-size: clamp(1.75rem, 3.4vw, 3.125rem);
  line-height: 1.15;
  letter-spacing: -0.022em;
  color: var(--color-heading);
  margin: 0;
}
.features-lede { display: grid; gap: 14px; max-width: 52rem; }
.features-lede p { margin: 0; font-size: 1rem; line-height: 1.55; color: var(--color-text); }

.features-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  align-items: start;
}

.features-col {
  display: grid;
  gap: 12px;
  align-content: start;
}

.f-row {
  border: 1px solid rgba(0, 0, 0, 0.08);
  border-radius: 12px;
  background: var(--color-bg);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  overflow: hidden;
}
.f-row.is-open {
  border-color: rgba(0, 0, 0, 0.16);
  box-shadow: 0 6px 16px -10px rgba(0, 0, 0, 0.18);
}

.f-row-title {
  margin: 0;
}

.f-row-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  width: 100%;
  padding: 14px 16px;
  background: transparent;
  border: 0;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--color-heading);
}
.f-row-head:hover .f-title { color: var(--color-heading); }

.f-title {
  margin: 0;
  font-size: 0.9375rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--color-heading);
}

.f-toggle {
  width: 26px;
  height: 26px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.04);
  color: var(--color-heading);
  transition: transform 0.25s ease, background 0.2s ease, color 0.2s ease;
}
.f-row.is-open .f-toggle {
  transform: rotate(45deg);
  background: var(--color-heading);
  color: var(--color-white);
}

.f-body {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.f-row.is-open .f-body { grid-template-rows: 1fr; }

.f-body-inner {
  overflow: hidden;
  min-height: 0;
  padding: 0 16px;
  color: var(--color-text);
  font-size: 0.9375rem;
  line-height: 1.55;
}
.f-row.is-open .f-body-inner {
  padding-bottom: 16px;
}

@media (max-width: 880px) {
  .features-list { grid-template-columns: 1fr; }
}

